mapper.select:
SELECT *, 1 as no
FROM faq_mgmt
where faq_id = #{id}

mapper.insert:
INSERT INTO faq_mgmt (
faq_que_ctnt, faq_ans_ctnt, cre_usr_id, cre_dt, upd_usr_id, upd_dt
)
VALUES (
#{faqQueCtnt}, #{faqAnsCtnt}, #{creUsrId}, #{creDt}, #{updUsrId},
#{updDt}
)

mapper.update:
UPDATE faq_mgmt
faq_que_ctnt = #{faqQueCtnt}, faq_ans_ctnt = #{faqAnsCtnt}, cre_usr_id = #{creUsrId}, cre_dt = #{creDt}, upd_usr_id = #{updUsrId}, upd_dt = #{updDt},
WHERE faq_id = #{faqId}

mapper.select:
SELECT
*,
count(*) over() AS ttl_no,
count(*) over() + 1 - ROW_NUMBER() over(ORDER BY cre_dt DESC, faq_id) as no
FROM faq_mgmt
WHERE 1=1


	AND UPPER(faq_que_ctnt) LIKE #{faqQueCtnt}



	AND UPPER(faq_ans_ctnt) LIKE #{faqAnsCtnt}

ORDER BY cre_dt DESC, faq_id

	OFFSET ${offset}


	LIMIT ${limit}
